from pathlib import Path
from html import escape
from format_lecon import paras,table,ABBR
from medicaments import quote
ABBR.update({'AMX':'amoxicilline','CLV':'acide clavulanique','ClCr':'clairance de la créatinine','PCU':'phénylcétonurie','BSAC':'Société britannique de chimiothérapie antimicrobienne'})
def extrait(n,debut,fin):
 s=(Path(__file__).resolve().parents[1]/f'evidence/AIPS_{n}.txt').read_text();a=s.index(debut);b=s.index(fin,a+len(debut));return '<blockquote><p>« '+escape(' '.join(s[a:b].splitlines()))+' »</p></blockquote>'
def adulte(l):
 d=paras('Augmentin associe amoxicilline, qui inhibe la synthèse de paroi bactérienne, et acide clavulanique, inhibiteur de certaines bêta-lactamases. La couverture dépend de la sensibilité des germes et ne garantit pas une activité sur un staphylocoque résistant à la méticilline.',
 'Le comprimé à 625 mg contient 500 mg d’amoxicilline et 125 mg d’acide clavulanique, autorisation suisse 45674. Le comprimé à 1 g contient 875/125 mg, autorisation 53692. Les notices et les présentations suisses ont été vérifiées ; la notice commune est datée de septembre 2026.')
 d+=quote('45674',['Augmentin doit être utilisé conformément','Infections de la peau et des tissus mous:','Pour les infections légères, modérées et sévères,','Augmentin comprimés filmés ne convient pas'])
 d+=paras('Dans une forme préseptale légère ambulatoire sélectionnée, la dose usuelle adulte de la notice est 625 mg trois fois par jour. Elle correspond à 500/125 mg par prise, pas à 625 mg d’amoxicilline. L’indication AIPS est formulée comme infection de peau et tissus mous à germes sensibles, sans mention nominative de cellulite préseptale.',
 'La durée de sept jours retenue comme repère adulte vient du guide européen près des yeux, pas de la notice. Elle reste adaptée à l’évolution et au protocole local après examen. Une forme grave ou douteuse nécessite un parcours hospitalier, pas une simple augmentation des comprimés.')
 d+=extrait('45674','Adultes et enfants de plus de 40 kg:\nClairance','Patients âgés\n')
 d+=paras('En insuffisance rénale, l’intervalle entre les prises du comprimé 625 mg est adapté. Il est de douze heures pour une clairance de 10 à 30 ml/min et de vingt-quatre heures sous 10 ml/min. La dialyse demande un schéma prescrit spécifiquement. Les comprimés à 1 g sont réservés à une clairance supérieure à 30 ml/min.',
 'La personne âgée garde la dose adulte si sa fonction rénale le permet. Une insuffisance hépatique exige prudence et surveillance ; aucun palier chiffré ne doit être inventé. Le choix final tient compte de la gravité, des cultures et des autres médicaments.')
 d+=quote('45674',["L'usage d'Augmentin est contre-indiqué",'Les patients qui souffrent de mononucléose infectieuse'])
 d+=paras('Rechercher précisément les réactions antérieures aux pénicillines, céphalosporines et excipients, ainsi qu’un ictère ou trouble hépatique sous cette association. Une allergie sévère exige une alternative adaptée à la porte d’entrée et aux germes, avec avis spécialisé. Aucun remplacement universel non vérifié n’est proposé ici.',
 'Arrêter et faire évaluer immédiatement une réaction allergique, une éruption sévère avec lésions muqueuses ou un malaise. Une diarrhée sévère, persistante ou sanglante peut signaler une colite à Clostridium difficile ; éviter les ralentisseurs du transit et consulter.',
 'Nausées et diarrhée sont possibles. Les complications rares comprennent atteinte hépatique, atteinte rénale et convulsions favorisées par une accumulation. Vomissements prolongés après une prise peuvent relever d’une réaction médicamenteuse et ne doivent pas être systématiquement attribués à l’infection.',
 'Les anticoagulants oraux exigent une surveillance de la coagulation. Revoir méthotrexate, mycophénolate, allopurinol, probénécide et autres traitements. Pour la contraception orale, la notice mentionne une précaution supplémentaire ; vérifier le conseil individuel avec le prescripteur, notamment en cas de vomissements ou diarrhée.')
 d+='<h3>Grossesse et allaitement : texte officiel</h3>'+extrait('45674','Les études de reproduction menées chez l\'animal','Effet sur l’aptitude à la conduite')
 d+=paras('Cette notice réserve l’utilisation pendant la grossesse à une nécessité absolue et déconseille l’allaitement pendant le traitement. Le choix d’un antibiotique compatible avec la situation se discute avec le prescripteur ; ne pas décider d’un sevrage à partir de cette fiche. Le signal obstétrical cité concerne une prophylaxie après rupture prématurée des membranes, pas une quantification du risque de toute cure pour cellulite.',
 'Prendre au début d’un repas avec de l’eau selon la notice. La barre du comprimé à 1 g facilite la prise sans définir deux demi-doses. Cette fenêtre ne remplace pas la notice de suspension pour un enfant de moins de 40 kg. Une infection orbitaire ne relève pas de ce seul traitement oral.')
 return l.subwindow('coamoxi-adulte','Amoxicilline–clavulanate : comprimés et sécurité',d,(38,40))
def enfant(l):
 d=paras('Co-Amoxi-Mepha 156,25 et 312,5 sont des poudres pour suspension buvable, autorisation suisse 53982, notice août 2026. Après reconstitution, 5 ml contiennent respectivement 125/31,25 mg ou 250/62,5 mg d’amoxicilline/acide clavulanique. Le rapport est 4:1.',
 'La présentation 457 contient 400/57 mg pour 5 ml et a des indications propres, sans infection de peau et tissus mous dans la liste citée. Elle ne remplace donc pas automatiquement les deux suspensions 4:1 pour cette indication. Le nombre affiché est la somme des deux composants, pas la quantité d’amoxicilline.')
 d+=extrait('53982','Enfants jusqu\'à 40 kg\nDirectives posologiques générales','Co-Amoxi-Mepha suspension 457\nLa dose journalière')
 d+=quote('53982',['Pour le traitement des infections chez les nouveau-nés et les nourrissons jusqu\'à 3 mois'])
 d+=paras('Les valeurs de cette citation sont des doses quotidiennes, réparties en trois prises pour les formes 156,25 et 312,5. Pour lire la dose en amoxicilline, utiliser le composant AMX explicitement indiqué entre parenthèses. Ne pas confondre mg/kg/jour, mg/kg/prise et somme des deux substances.',
 'La notice distingue moins de deux ans et plus de deux ans dans ses directives générales et fournit ensuite des tableaux de poids avec des âges approximatifs. À la limite d’âge ou de poids, le pédiatre fixe le schéma à partir du poids mesuré et de la situation clinique. Le tableau ne décide pas à lui seul d’une prise en charge ambulatoire.',
 'Un nouveau-né ou nourrisson jusqu’à trois mois ne reçoit pas un schéma oral inventé par extrapolation. La notice renvoie à la forme intraveineuse, et une infection périoculaire à cet âge appelle une évaluation hospitalière. Une forme sévère, une mauvaise tolérance orale ou un examen oculaire impossible imposent aussi une réévaluation hospitalière.',
 'Le prescripteur indique le volume par prise, la concentration exacte et la durée. Utiliser la seringue fournie et vérifier le calcul à chaque changement de présentation. Une cuillère domestique et un échange de flacon à volume identique ne conviennent pas.')
 d+=extrait('53982','Enfants jusqu\'à 40 kg:\nClairance de la créatinine','Mode d\'administration\n')
 d+=quote('53982',["L'usage de Co-Amoxi-Mepha est contre-indiqué",'Les patients qui souffrent de mononucléose infectieuse'])
 d+=paras('Les contre-indications allergiques et les antécédents hépatiques doivent être recherchés pour cette suspension aussi. La fonction rénale modifie dose ou intervalle ; la table citée distingue les composants et précise les maxima. Une décision de dialyse ou d’insuffisance rénale pédiatrique relève d’un prescripteur expérimenté.',
 'La présence d’aspartame importe en cas de phénylcétonurie. L’alcool benzylique de l’arôme exige une attention particulière chez les plus jeunes. La notice demande de ne pas utiliser plus d’une semaine avant trois ans sauf avis médical ou pharmaceutique. Il s’agit d’une précaution d’excipient, pas d’une autorisation de traiter à domicile toute infection une semaine.',
 'Réaction allergique, éruption sévère, diarrhée sanglante ou vomissements prolongés après la prise imposent une évaluation. Une baisse de diurèse ou un ictère doit également être signalé. Revoir les autres traitements et surveiller la tolérance, la fièvre et les signes oculaires.')
 d+='<h3>Grossesse et allaitement : notice de suspension</h3>'+extrait('53982','Les études de reproduction menées chez l\'animal','Effet sur l’aptitude à la conduite')
 d+=quote('53982',['Après reconstitution, les suspensions reconstituées peuvent être conservées','Agiter avant chaque utilisation.'])
 d+=paras('La préparation est habituellement reconstituée par le pharmacien. Les sept jours au réfrigérateur entre 2 et 8 °C concernent la conservation ; ils ne définissent pas automatiquement la durée de la cellulite. La durée clinique est fixée et réévaluée selon la sévérité, le guide local et la réponse.',
 'Les recommandations européennes pédiatriques citées distinguent cinq jours pour une forme légère et sept jours après une forme nécessitant une séquence intraveineuse puis orale. Elles ne constituent ni une dose AIPS, ni un protocole suisse universel. Un cas orbitaire suit un autre parcours.')
 return l.subwindow('coamoxi-enfant','Suspension pédiatrique : composants, âge et calcul',d,(9,39))
